function (time_range, granules) 
{
    col_cuts <- calendar_axis_cuts(time_range, granules$cols, 
        fallback = time_range, name = "cols")
    row_grid <- calendar_row_cuts(col_cuts, granules$rows)
    row_window <- c(row_grid[1], row_grid[1] + max(diff(row_grid)))
    span <- calendar_span(col_cuts, row_grid)
    list(granules = granules, col_cuts = col_cuts, row_grid = row_grid, 
        row_window = row_window, span = span, block_cuts = calendar_axis_cuts(span, 
            granules$blocks, name = "blocks"), pane_cuts = calendar_axis_cuts(span, 
            granules$panes, name = "panes"))
}
