function (cells = day(1L), rows = week(1L), blocks = NULL, panes = month(1L), 
    cols = quarter(1L), pane_spacing = 0.25, col_spacing = 0.1, 
    cell_ratio = NULL, label_cells = "{cyc(day, month)}", label_rows = NULL, 
    label_blocks = NULL, label_panes = "{cyc(month, year, label = TRUE, abbreviate = TRUE)}", 
    label_cols = NULL, time = "x", xlim = NULL, ylim = NULL, 
    expand = FALSE, default = FALSE, clip = "on", coord = coord_cartesian()) 
{
    rows_missing <- missing(rows)
    cols_missing <- missing(cols)
    cells_quo <- enquo(cells)
    rows_quo <- enquo(rows)
    blocks_quo <- enquo(blocks)
    panes_quo <- enquo(panes)
    cols_quo <- enquo(cols)
    pane_spacing <- check_spacing(pane_spacing)
    col_spacing <- check_spacing(col_spacing)
    cell_ratio <- check_ratio(cell_ratio)
    label_formats <- list(cell = check_labels(label_cells), row = check_labels(label_rows), 
        block = check_labels(label_blocks), pane = check_labels(label_panes), 
        col = check_labels(label_cols))
    loop_coord <- specialize_coord_loop(ggplot2::ggproto(NULL, 
        CoordLoop(coord), time = time, is_flipped = isTRUE(time == 
            "y"), limits = list(x = xlim, y = ylim), expand = expand, 
        default = default, clip = clip))
    if (!inherits(loop_coord, "CoordCartesian")) {
        cls <- setdiff(class(loop_coord), "CoordLoop")[1L]
        cli::cli_abort("{.fn coord_calendar} does not support {.cls {cls}}.")
    }
    if (!is.null(cell_ratio) && !is.null(loop_coord$ratio)) {
        cli::cli_abort(c("{.arg cell_ratio} and {.arg coord}'s own {.arg ratio} cannot both be\n       set.", 
            i = "Each fixes the panel's aspect ratio."))
    }
    ggplot2::ggproto(NULL, CoordCalendar(loop_coord), cells_quo = cells_quo, 
        rows_quo = rows_quo, rows_missing = rows_missing, blocks_quo = blocks_quo, 
        panes_quo = panes_quo, cols_quo = cols_quo, cols_missing = cols_missing, 
        pane_spacing = pane_spacing, col_spacing = col_spacing, 
        cell_ratio = cell_ratio, label_formats = label_formats, 
        call = current_call())
}
